#pragma once

#include "memory_region.hpp"

#include <spdlog/spdlog.h>
#include <systemc>
#include <tlm>
#include <tlm_utils/simple_target_socket.h>

#include <cstdint>

#include <array>

/**
 * UART model (16550-compatible) for AE350 platform.
 *
 * Register map (from ae350.h UART_RegDef):
 *   0x00  IDREV   - ID and Revision Register (RO)
 *   0x10  CFG     - Hardware Configure Register (RO)
 *   0x14  OSCR    - Over Sample Control Register (RW)
 *   0x20  RBR/THR/DLL - Receiver Buffer / Transmitter Holding / Divisor Latch
 * LSB 0x24  IER/DLM - Interrupt Enable / Divisor Latch MSB 0x28  IIR/FCR -
 * Interrupt Identification / FIFO Control 0x2C  LCR     - Line Control Register
 *   0x30  MCR     - Modem Control Register
 *   0x34  LSR     - Line Status Register
 *   0x38  MSR     - Modem Status Register
 *   0x3C  SCR     - Scratch Register
 */
template<std::size_t BusWidth = 32>
class UART : public sc_core::sc_module
{
public:
  const MemoryRegion region;
  tlm_utils::simple_target_socket<UART, BusWidth> socket{"tsck"};

  UART(const sc_core::sc_module_name& name, const MemoryRegion& region)
      : sc_core::sc_module{name}, region(region)
  {
    this->socket.register_b_transport(this, &UART::b_transport);
    reset();
  }

  void b_transport(tlm::tlm_generic_payload& trans, sc_core::sc_time& /*delay*/)
  {
    handle_trans(trans);
    trans.set_response_status(tlm::TLM_OK_RESPONSE);
  }

private:
  // Registers
  uint32_t idrev = 0x00112300; // some default ID
  uint32_t cfg = 0;
  uint32_t oscr = 0;
  uint32_t rbr = 0; // RBR (read) / THR (write) / DLL (when DLAB=1)
  uint32_t ier = 0; // IER (normal) / DLM (when DLAB=1)
  uint32_t iir =
    0x01; // IIR (read) / FCR (write), bit0=1 means no pending interrupt
  uint32_t lcr = 0;
  uint32_t mcr = 0;
  uint32_t lsr = 0;
  uint32_t msr = 0;
  uint32_t scr = 0;

  // Internal state
  uint32_t dll = 0; // Divisor Latch LSB
  uint32_t dlm = 0; // Divisor Latch MSB
  bool fifo_enabled = false;

  static constexpr uint32_t LSR_RDR = 0x01; // Receiver Data Ready

  // THRE: 0 means the transmitter is still busy, 1 means it's ready to accept a
  // new character
  static constexpr uint32_t LSR_THRE =
    0x20; // Transmitter Holding Register Empty
  static constexpr uint32_t LSR_TEMT = 0x40; // Transmitter Empty
  static constexpr uint32_t LCR_DLAB = 0x80; // Divisor Latch Access Bit

  void reset()
  {
    idrev = 0x00112300;
    cfg = 0;
    oscr = 0;
    rbr = 0;
    ier = 0;
    iir = 0x01;
    lcr = 0;
    mcr = 0;
    lsr = LSR_THRE | LSR_TEMT; // TX ready
    msr = 0;
    scr = 0;
    dll = 0;
    dlm = 0;
    fifo_enabled = false;
  }

  bool dlab() const { return (lcr & LCR_DLAB) != 0; }

  void handle_trans(tlm::tlm_generic_payload& trans)
  {
    const auto addr = trans.get_address();
    const auto offset = addr - region.base_address;
    const auto len = trans.get_data_length();
    auto* ptr = trans.get_data_ptr();

    spdlog::debug("uart: {}, addr={:#x}, offset={:#x}, len={}",
                  trans.is_read() ? "read" : "write", addr, offset, len);

    if (trans.is_read()) {
      uint32_t val = handle_read(offset);
      // Write value to payload (little-endian)
      for (unsigned i = 0; i < len && i < 4; ++i)
        ptr[i] = (val >> (i * 8)) & 0xFF;
    } else {
      // Read value from payload (little-endian)
      uint32_t val = 0;
      for (unsigned i = 0; i < len && i < 4; ++i)
        val |= static_cast<uint32_t>(ptr[i]) << (i * 8);
      handle_write(offset, val);
    }
  }

  uint32_t handle_read(uint64_t offset)
  {
    switch (offset) {
    case 0x00:
      return idrev;
    case 0x10:
      return cfg;
    case 0x14:
      return oscr;
    case 0x20: // RBR or DLL
      if (dlab())
        return dll;
      return rbr;
    case 0x24: // IER or DLM
      if (dlab())
        return dlm;
      return ier;
    case 0x28:
      return iir; // IIR
    case 0x2C:
      return lcr;
    case 0x30:
      return mcr;
    case 0x34:
      return lsr;
    case 0x38:
      return msr;
    case 0x3C:
      return scr;
    default:
      spdlog::warn("uart: read from unknown offset {:#x}", offset);
      return 0;
    }
  }

  void handle_write(uint64_t offset, uint32_t val)
  {
    switch (offset) {
    case 0x14: // OSCR
      oscr = val;
      break;
    case 0x20: // THR or DLL
      if (dlab()) {
        dll = val & 0xFF;
      } else {
        // THR: transmit character
        char c = static_cast<char>(val & 0xFF);
        fmt::print("{}", c);
        // LSR: TX is always ready in simulation
        lsr |= LSR_THRE | LSR_TEMT;
      }
      break;
    case 0x24: // IER or DLM
      if (dlab()) {
        dlm = val & 0xFF;
      } else {
        ier = val;
      }
      break;
    case 0x28: // FCR (write-only)
      if (val & 0x01)
        fifo_enabled = true;
      // Bits 1,2: reset RX/TX FIFO (no-op in sim)
      iir = (iir & ~0xC0) | (fifo_enabled ? 0xC0 : 0x00);
      break;
    case 0x2C: // LCR
      lcr = val;
      break;
    case 0x30: // MCR
      mcr = val;
      break;
    case 0x38: // MSR (normally RO, but allow writes for testing)
      msr = val;
      break;
    case 0x3C: // SCR
      scr = val;
      break;
    default:
      spdlog::warn("uart: write to unknown offset {:#x}, val={:#x}", offset,
                   val);
      break;
    }
  }
};

