19	// NOTE: this header is #include'd inside the SimControl class body
20	// (sim_control.hpp), so the functions here are member functions with implicit
21	// `this`. The helpers below are member functions for the same reason -- they
22	// reach `data_region`, which is a private SimControl member.
23	
24	// Convert a guest VA to a host-pointer into data_region.data. Subtracts
25	// region.base_address so the index lands at the correct offset whether the
26	// region starts at 0x0 (Tier-1, no shared mem) or at 0x80000000 (Tier-2,
27	// --shared-mem-base, narrowed RAM). Without this, a guest stack VA like
28	// 0x80700000 indexes 2 GiB into the data span, which is in-bounds for the
29	// 0x90000000-byte owned buffer but OOB for a 128 MiB shared mmap.
30	template<typename T = uint8_t>
31	inline T* guest_va_to_host(uint64_t va)
32	{
33	  const uint64_t off = va - data_region.region.base_address;
34	  return reinterpret_cast<T*>(data_region.data.data() + off);
35	}
36	
37	// Newlib's <sys/_default_fcntl.h> uses BSD-derived O_* values that differ
38	// from the Linux ABI -- e.g. O_CREAT=0x200 in newlib vs 0x40 in Linux,
39	// O_TRUNC=0x400 vs 0x200. Pass-through to host open() with newlib values
40	// would clear O_CREAT/O_EXCL and silently accept O_APPEND, so a fopen("w+")
41	// for a non-existent file fails with ENOENT. Translate flag-by-flag.
42	inline int newlib_to_linux_open_flags(uint64_t newlib_flags)
43	{
44	  constexpr uint64_t NL_RDONLY  = 0;
45	  constexpr uint64_t NL_WRONLY  = 1;
46	  constexpr uint64_t NL_RDWR    = 2;
47	  constexpr uint64_t NL_APPEND  = 0x0008;
48	  constexpr uint64_t NL_CREAT   = 0x0200;
49	  constexpr uint64_t NL_TRUNC   = 0x0400;
50	  constexpr uint64_t NL_EXCL    = 0x0800;
